type Child = Element | string;
interface Element { tag: string; props: Record<string, string | number | boolean>; children: Child[] }
const node = (tag: string, props: Element["props"] = {}, ...children: Array<Child | Child[] | null | false | undefined>): Element => ({ tag, props, children: children.flatMap(child => child === null || child === false || child === undefined ? [] : Array.isArray(child) ? child : [child]) });
const esc = (value: string | number) => String(value).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
const voidTags = new Set(["img", "br", "hr"]);
function html(value: Child): string {
  if (typeof value === "string") return esc(value);
  const attributes = Object.entries(value.props).filter(([, v]) => v !== false).map(([key, v]) => v === true && key === "open" ? ` ${key}` : ` ${key}="${esc(String(v))}"`).join("");
  return `<${value.tag}${attributes}>${voidTags.has(value.tag) ? "" : value.children.map(html).join("") + `</${value.tag}>`}`;
}
const jsxNames: Record<string, string> = { class: "className", "stroke-width": "strokeWidth", "stroke-linecap": "strokeLinecap", "stroke-linejoin": "strokeLinejoin", "fill-opacity": "fillOpacity", "stroke-opacity": "strokeOpacity", "text-anchor": "textAnchor", "stop-color": "stopColor", "stop-opacity": "stopOpacity", "clip-path": "clipPath", "fill-rule": "fillRule", "clip-rule": "clipRule", "font-size": "fontSize", "font-family": "fontFamily", tabindex: "tabIndex" };
const js = (value: unknown) => JSON.stringify(value).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
function jsx(value: Child): string {
  if (typeof value === "string") return `{${js(value)}}`;
  const attributes = Object.entries(value.props).filter(([, v]) => v !== false).map(([key, v]) => ` ${jsxNames[key] ?? key}={${js(v)}}`).join("");
  return `<${value.tag}${attributes}${voidTags.has(value.tag) ? " />" : ">" + value.children.map(jsx).join("") + `</${value.tag}>`}`;
}

