export function createImmersiveDesignBrief(input: Pick<ImmersiveBusiness, "businessName" | "industry" | "location">): Readonly<ImmersiveDesignBrief> {
  const identity = [input.businessName, input.industry, input.location].map(v => v.normalize("NFKC").trim().toLocaleLowerCase("en-AU")).join("|");
  const digest = createHash("sha256").update(identity).digest();
  const words = input.industry.toLocaleLowerCase("en-AU");
  const family: ImmersiveFamily = /(?:car\b|auto|detail|mechanic|motor|tyre|vehicle|carwash)/.test(words) ? "automotive"
    : /(?:gym|fitness|sport|boxing|martial|pilates|yoga|dance|strength|wellness|train)/.test(words) ? "movement"
    : /(?:fenc|plumb|electr|build|carpent|timber|roof|landscap|garden|trade|concret|paint|renovat|floor|clean|handyman|cabinet)/.test(words) ? "craft" : "editorial";
  const style = families[family], [background, foreground, accent, muted] = style.palettes[digest[1]! % style.palettes.length]!;
  const motif = /(?:garden|landscap|hortic|lawn)/.test(words) ? "botanical-terrace"
    : /(?:hair|salon|barber|beauty)/.test(words) ? "mirror-and-flow"
    : /(?:cafe|café|coffee|restaurant|dining|food|catering|bakery|bistro)/.test(words) ? "table-and-vessel"
    : family === "automotive" ? "sculpted-automotive" : family === "movement" ? "kinetic-ribbon" : family === "craft" ? "architectural-material" : "sculptural-arch";
  const motifHeadlines = motif === "botanical-terrace" ? ["A little greener.\nA little more possibility.", "Good spaces.\nRoom to grow.", "A fresh outlook.\nFrom the ground up."]
    : motif === "mirror-and-flow" ? ["A little ritual.\nA different feeling.", "Your next look.\nA fresh introduction.", "Make a little\ntime for yourself."]
    : motif === "table-and-vessel" ? ["Take a seat.\nStay a little longer.", "A taste of\nsomething different.", "Come for the flavour.\nStay for the feeling."] : style.headlines;
  const motifLabel = motif === "botanical-terrace" ? " / botanical forms and greener spaces" : motif === "mirror-and-flow" ? " / mirror, flow and a little ritual" : motif === "table-and-vessel" ? " / a table, a vessel and an invitation" : "";
  const layout = ["type-led", "image-led", "split-stage"][digest[0]! % 3]!;
  const sectionOrder = digest[2]! % 2 ? ["services", "story", "gallery", "contact"] : ["story", "services", "gallery", "contact"];
  return Object.freeze({ id: `immersive-v1-${digest.toString("hex").slice(0, 12)}`, family, direction: style.direction + motifLabel,
    palette: Object.freeze({ background: background!, foreground: foreground!, accent: accent!, muted: muted! }), layout,
    typography: style.typography[digest[3]! % style.typography.length]!, headline: motifHeadlines[digest[4]! % motifHeadlines.length]!,
    signature: digest.toString("hex").slice(0, 12), motif, sections: Object.freeze(sectionOrder) });
}

