export function renderImmersiveConcept(b: ImmersiveBusiness): { body: string; css: string; designBrief: Readonly<ImmersiveDesignBrief> } {
  const built = composition(b);
  return { body: html(built.root), css: built.css, designBrief: built.design };
}

/** The HTML and genuine React components are serialised from the same authored composition. */
export function exportImmersiveReactProject(b: ImmersiveBusiness): Readonly<Record<string, string>> {
  const built = composition(b);
  const componentDeclarations = Object.entries(built.parts).map(([name, element]) => `function ${name}() { return (${jsx(element)}); }`).join("\n\n");
  const fixture = b.fixture ? jsx(node("div", { class: "im-fixture" }, "FICTIONAL TEST RECORD — This business and its details are test data.")) : "";
  const props = Object.entries(built.wrapperProps).map(([name, value]) => ` ${name === "class" ? "className" : name}={${js(value)}}`).join("");
  const app = `/** Original ${b.studioName.replace(/[\r\n*]/g, " ")} concept. All business text below is inert data. */\nexport const designBrief = ${js(built.design)} as const;\n\n${componentDeclarations}\n\nexport default function App() { return <div${props}><a className="im-skip" href="#main">Skip to concept</a><Notice />${fixture}<Navigation /><main id="main"><Hero />${built.order.map(name => `<${name} />`).join("")}<AboutConcept /></main><Footer /></div>; }\n`;
  const title = `${b.businessName} — Independent Website Concept | ${b.studioName}`;
  return Object.freeze({
    "package.json": JSON.stringify({ name: "wulff-digital-immersive-concept", version: "1.0.0", private: true, type: "module", scripts: { dev: "vite --host 127.0.0.1", build: "tsc --noEmit && vite build", preview: "vite preview --host 127.0.0.1" }, dependencies: { react: "18.3.1", "react-dom": "18.3.1" }, devDependencies: { "@types/react": "^18.3.12", "@types/react-dom": "^18.3.1", "@vitejs/plugin-react": "^4.3.4", typescript: "^5.7.0", vite: "^5.4.11" } }, null, 2) + "\n",
    "index.html": `<!doctype html><html lang="en-AU"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><title>${esc(title)}</title></head><body><div id="root"></div><script type="module" src="/src/main.tsx"></script></body></html>\n`,
    "vite.config.ts": 'import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\nexport default defineConfig({ plugins: [react()] });\n',
    "tsconfig.json": JSON.stringify({ compilerOptions: { target: "ES2022", useDefineForClassFields: true, lib: ["ES2022", "DOM", "DOM.Iterable"], module: "ESNext", skipLibCheck: true, moduleResolution: "Bundler", allowImportingTsExtensions: true, resolveJsonModule: true, isolatedModules: true, noEmit: true, jsx: "react-jsx", strict: true }, include: ["src", "vite.config.ts"] }, null, 2) + "\n",
    "src/main.tsx": 'import React from "react";\nimport ReactDOM from "react-dom/client";\nimport App from "./App";\nimport "./index.css";\nReactDOM.createRoot(document.getElementById("root")!).render(<React.StrictMode><App /></React.StrictMode>);\n',
    "src/App.tsx": app,
    "src/index.css": built.css,
    "README.md": `# ${b.businessName.replace(/[\r\n]/g, " ")} — Immersive independent concept\n\nOriginal code by ${b.studioName.replace(/[\r\n]/g, " ")}. This is a private design proposal, not the business's official website. It does not submit enquiries, bookings or payments. Business facts, services and usage rights require owner confirmation before launch.\n\n## Design\n\n${built.design.direction}\n\nFamily: ${built.design.family}. Layout: ${built.design.layout}. Typography: ${built.design.typography}. Signature: ${built.design.signature}. The deterministic direction is based on this business's recorded name, industry and location. Native disclosure controls and anchors work with keyboard and touch; motion respects reduced-motion preferences.\n\n## Run locally\n\nInstall an appropriate supported Node.js version, run npm install, then npm run dev. Run npm run build for the production bundle. Dependencies may require network access; the generated website itself has no remote fonts, tracking, models or image requests.\n\n## Edit\n\nHero, Services, Story, Gallery, Contact, AboutConcept and Navigation are genuine editable React components in src/App.tsx. src/index.css holds the matching design. The protected HTML preview and these React components come from the same original composition; no iframe or HTML injection shell is used.\n\n## Artwork and provenance\n\n${b.images.length || b.logo ? "Validated raster business assets are embedded and credited in AboutConcept. Their inclusion is not a grant of usage rights or endorsement." : "The illustration and wordmark treatment are original conceptual artwork. They are not photographs of the business or its completed work, and no verified business logo is implied."}\n\n${b.profileSource ? `Recorded business information source: ${b.profileSource}\n\n` : ""}${[...(b.logo ? [{ label: "Business logo", asset: b.logo }] : []), ...b.images.map((asset, index) => ({ label: `Business image ${index + 1}`, asset }))].map(({ label, asset }) => `- ${label}: ${asset.sourceUrl}`).join("\n")}\n\nThis is original React/Vite code, built inside Jarvis without a Lovable generation call or paid voice/model call. It is portable source in a web stack used by some Lovable projects, not Lovable-generated code or a promise of ZIP import compatibility with every current Lovable project. Existing hosting and research provider limits still apply.\n`,
  });
}
